        print('case values:', [c['value'] for c in inp['cases']])
        for case in inp['cases']:
            if case['value']=='mtx':
                for sub in case['inputs']:
                    print('sub', sub['name'], sub['type'])
                    if sub['type']=='conditional':
                        print(' test', json.dumps(sub['test_param'], indent=2))
                        print(' cases', [c['value'] for c in sub['cases']])
